def compute(vars):
    issued_securities = vars["v1"]
    exercise_price = vars["v2"]

    total_value_dollars = issued_securities * exercise_price
    total_value_millions = total_value_dollars * 0.000001

    return {
        "value": total_value_millions,
        "trace": {
            "issued_securities": issued_securities,
            "exercise_price": exercise_price,
            "total_value_dollars": total_value_dollars,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency"
            }
        }
    }
